declarations.formal_type:
∀ {C : Type u_1} [inst : CategoryTheory.Category.{u_2, u_1} C] [inst_1 : CategoryTheory.Abelian.{u_2, u_1} C] {X Y : C}
  (f : Quiver.Hom.{u_2, u_1} X Y) [inst_2 : CategoryTheory.Mono.{u_2, u_1} f]
  (P : CategoryTheory.Subobject.{u_2, u_1} Y),
  Eq.{max (u_1 + 1) (u_2 + 1)}
    (CategoryTheory.Functor.obj.{max u_1 u_2, max u_1 u_2, max u_1 u_2, max u_1 u_2}
      (CategoryTheory.Subobject.map.{u_2, u_1} f)
      (CategoryTheory.Functor.obj.{max u_1 u_2, max u_1 u_2, max u_1 u_2, max u_1 u_2}
        (CategoryTheory.Subobject.pullback.{u_2, u_1} f) P))
    (Min.min.{max u_1 u_2} P (CategoryTheory.Subobject.mk.{u_2, u_1} f))

∀ {C : Type u_1} [inst : CategoryTheory.Category.{u_2, u_1} C] [inst_1 : CategoryTheory.Abelian.{u_2, u_1} C] {X Y : C}
  (g : Quiver.Hom.{u_2, u_1} X Y) (P : CategoryTheory.Subobject.{u_2, u_1} X),
  Eq.{max (u_1 + 1) (u_2 + 1)}
    (CategoryTheory.Functor.obj.{max u_1 u_2, max u_1 u_2, max u_1 u_2, max u_1 u_2}
      (CategoryTheory.Subobject.pullback.{u_2, u_1} g)
      (CategoryTheory.Functor.obj.{max u_1 u_2, max u_1 u_2, max u_1 u_2, max u_1 u_2}
        (CategoryTheory.Subobject.exists.{u_2, u_1} g) P))
    (Max.max.{max u_1 u_2} P (CategoryTheory.Limits.kernelSubobject.{u_2, u_1} g))
